{
     "title": "CSCI-610: Foundations of Computer Graphics",
     "learningObjectives": [
       "Define the core components of the hardware rasterization pipeline and explain their sequential processing of geometric primitives.",
       "Apply coordinate transformations and projection matrices to map 3-D scene geometry into a 2-D image plane for rendering.",
       "Evaluate the role of hardware shaders and rasterization techniques in determining visual correctness and performance in interactive graphics."
     ],
     "beats": [
       {
         "title": "Introduction to Raster Graphics Pipeline",
         "claim": "The OpenGL graphics pipeline processes vertices through programmable shader stages before rasterization.",
         "example": "A triangle mesh is passed to vertex shaders that compute position and normal attributes for each vertex.",
         "visualDirection": "Display a flowchart showing vertex input -> vertex shader -> primitive assembly -> clipping -> rasterization -> fragment shader -> framebuffer.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Primitive Assembly and Clipping",
         "claim": "Primitive assembly groups vertices into points, lines, or triangles, and clipping removes portions outside the view volume.",
         "example": "A polygon with one vertex outside the camera frustum is clipped to intersect the view volume boundaries.",
         "visualDirection": "Show a 3-D polygon being clipped by a view frustum, highlighting the clipped-out segment and the resulting clipped primitive.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Rasterization and Interpolation",
         "claim": "Rasterization converts primitives into fragment candidates, and interpolation produces per-fragment values from vertex outputs.",
         "example": "A triangle is rasterized into a set of pixels, with color and normal values interpolated across each pixel based on barycentric coordinates.",
         "visualDirection": "Illustrate a triangle being rasterized into a grid of pixels, with color gradients showing interpolated vertex attributes.",
         "sourceIds": ["khronos-opengl", "mit-computer-graphics"]
       },
       {
         "title": "Fragment Processing and Depth Testing",
         "claim": "Fragment processing computes values for framebuffer operations, and depth testing resolves visibility according to stored depth values.",
         "example": "A backface-occluded triangle is discarded because its depth value is greater than the stored depth buffer value at that pixel.",
         "visualDirection": "Show a depth buffer comparison where a closer triangle overwrites a farther triangle's pixel values.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Blending and Coordinate Spaces",
         "claim": "Blending combines a fragment result with an existing framebuffer value, and coordinate spaces, sampling, and numerical precision must remain explicit.",
         "example": "A semi-transparent overlay is blended with the underlying scene using alpha blending to produce a final pixel color.",
         "visualDirection": "Demonstrate alpha blending by showing a transparent shape merging with a solid background, highlighting the alpha channel calculation.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Geometric Modeling and Transformations",
         "claim": "Computer graphics uses geometric models to represent objects and scenes, and transformations position and orient geometry within coordinate systems.",
         "example": "A 3-D model is translated, rotated, and scaled using transformation matrices to position it in the scene.",
         "visualDirection": "Show a 3-D object being transformed through space, with axes and matrix values displayed alongside the transformed geometry.",
         "sourceIds": ["mit-computer-graphics"]
       },
       {
         "title": "Viewing and Projection",
         "claim": "Viewing maps a scene through a camera model to an image, and projections convert 3-D coordinates into 2-D image plane coordinates.",
         "example": "A perspective projection matrix converts 3-D world coordinates into 2-D screen coordinates, simulating camera depth.",
         "visualDirection": "Illustrate a camera model projecting 3-D scene geometry onto a 2-D image plane, showing the projection matrix in action.",
         "sourceIds": ["mit-computer-graphics"]
       },
       {
         "title": "Shading and Texture Mapping",
         "claim": "Shading models how light, material, and geometry determine appearance, and texture mapping associates image data with geometric surfaces.",
         "example": "A diffuse shading model computes surface brightness based on light direction and surface normal, while a texture map applies a 2-D image to a 3-D surface.",
         "visualDirection": "Show a 3-D surface with diffuse shading and a texture overlay, highlighting the light direction and normal vector calculations.",
         "sourceIds": ["mit-computer-graphics"]
       },
       {
         "title": "Hardware Shaders and Rasterization Focus",
         "claim": "The course emphasizes the hardware rasterization pipeline including the use of hardware shaders to process fragment data efficiently.",
         "example": "A fragment shader computes lighting and color values for each pixel in parallel on the GPU, accelerating rasterization.",
         "visualDirection": "Display a GPU architecture diagram highlighting shader cores processing fragment data during the rasterization stage.",
         "sourceIds": ["rit-csci-610", "khronos-opengl"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Visual correctness follows from explicit conventions, assumptions, sampling decisions, and measurable error in rendering pipelines.",
         "example": "A renderer checks anti-aliasing, depth precision, and sampling rates to ensure measurable error remains within acceptable bounds.",
         "visualDirection": "Show a checklist graphic with items like 'Verify depth buffer precision', 'Check sampling rates', 'Validate coordinate transformations', and 'Measure visual error'.",
         "sourceIds": ["mit-computer-graphics"]
       }
     ]
   }
